def recount_reactions(apps, schema_editor):
    """Счётчики лайков могли разойтись с реальными реакциями, пересчитываем."""
    Post = apps.get_model('news', 'Post')
    PostReaction = apps.get_model('news', 'PostReaction')
    for post in Post.objects.all():
        reactions = PostReaction.objects.filter(post=post)
        Post.objects.filter(pk=post.pk).update(
            likes=reactions.filter(is_like=True).count(),
            dislikes=reactions.filter(is_like=False).count(),
        )


